import { BASIS_TEXT, labelFor } from '@/modules/financials';
import type { DescriptorTable } from './descriptor';

/**
 * The short human string shown against every evidence item (EVIDENCE_MODEL.md §2.2).
 *
 * "It is **always** generated by the server from the referenced object; the AI contract carries no
 * `label` field (R2-C-08)." That is the whole point of this file existing separately from the
 * producers: a label is written once, from the object, by code — never taken from a model, and
 * never composed at render time from whatever the drawer happens to have loaded, which would let
 * the same item read differently in two places.
 *
 * Everything here is pure. The caller fetches the referenced object; this only names it. The
 * accountant's register is used throughout (`UX_ARCHITECTURE.md §304`: the technical term is what
 * appears "on Money sub-pages, in Reports and in the AI's Evidence section, where an accountant may
 * be reading"), from the one canonical table (ADR-037).
 */

export interface MetricSnapshotLabelInput {
  readonly metricKey: string;
  /** `fiscal_periods.label`, e.g. "Mar 2026". */
  readonly periodLabel: string | null;
  /** `metric_snapshots.basis`. */
  readonly basis: string;
  /** For a dimensioned snapshot: the counterparty or account it is about. */
  readonly dimensionLabel?: string | null;
}

/** "Revenue, Mar 2026 — from your accounts" (§2.2). */
export function metricSnapshotLabel(input: MetricSnapshotLabelInput): string {
  const metric = labelFor(input.metricKey).technical;
  const parts = [input.dimensionLabel ? `${metric} — ${input.dimensionLabel}` : metric];
  if (input.periodLabel) parts.push(input.periodLabel);
  const head = parts.join(', ');
  const basis = BASIS_TEXT[input.basis];
  /*
   * The basis is dropped rather than guessed when the enum grows a value this table has not been
   * taught. A label reading "Revenue, Mar 2026" is incomplete; one reading "Revenue, Mar 2026 —
   * undefined" is wrong, and it is the sentence a reader uses to decide whether to trust a number.
   */
  return basis ? `${head} — ${basis.toLowerCase()}` : head;
}

/** "Calculated 3 Apr 2026, engine 1.4.0". */
export function calculationRunLabel(input: {
  readonly engineVersion: string;
  readonly finishedAt: string | null;
}): string {
  const when = input.finishedAt === null ? null : formatDay(input.finishedAt);
  return when === null
    ? `Calculation, engine ${input.engineVersion}`
    : `Calculated ${when}, engine ${input.engineVersion}`;
}

/** The plural noun each descriptor table selects, in the register a reader would use. */
const TABLE_NOUN: Readonly<Record<DescriptorTable, string>> = {
  ledger_entries: 'ledger entries',
  bank_transactions: 'bank transactions',
  invoices: 'invoices',
  period_balances: 'report balances',
  metric_snapshots: 'figures',
};

/**
 * "The ledger entries behind Revenue, Mar 2026".
 *
 * No count: the label is written when the bundle is built and the count is whatever the resolver
 * returns when somebody opens it. A stored count would be a second, staler answer to a question the
 * drawer already answers exactly, and §6 requires the live one to reconcile against the metric.
 */
export function queryLabel(input: {
  readonly table: DescriptorTable;
  readonly ofMetricLabel: string;
}): string {
  return `The ${TABLE_NOUN[input.table]} behind ${input.ofMetricLabel}`;
}

/** "4000 Sales", or just the name when the chart has no codes. */
export function accountLabel(input: {
  readonly code: string | null;
  readonly name: string;
}): string {
  return input.code ? `${input.code} ${input.name}` : input.name;
}

export function counterpartyLabel(input: { readonly name: string }): string {
  return input.name;
}

/** "Invoice INV-1042, Acme Ltd, £4,200" (§2.2) — the pinned-record register. */
export function invoiceLabel(input: {
  readonly invoiceNumber: string | null;
  readonly counterpartyName: string | null;
  readonly formattedAmount: string | null;
}): string {
  const parts = ['Invoice'];
  if (input.invoiceNumber) parts[0] = `Invoice ${input.invoiceNumber}`;
  if (input.counterpartyName) parts.push(input.counterpartyName);
  if (input.formattedAmount) parts.push(input.formattedAmount);
  return parts.join(', ');
}

/** UK long-ish date, matching the rest of the product ("3 Apr 2026"). */
function formatDay(iso: string): string | null {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}
